    double n;
    double w, x, y, z;
    int sign = 1;

    if ((q == NULL) || (canonical == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(q->w)) || (!isfinite(q->x)) || (!isfinite(q->y)) || (!isfinite(q->z))) {
        *canonical = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    n = sqrt(q->w * q->w + q->x * q->x + q->y * q->y + q->z * q->z);
    if ((!isfinite(n)) || (n <= ADCS_EPS_QUAT)) {
        *canonical = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    w = q->w / n;
    x = q->x / n;
    y = q->y / n;
    z = q->z / n;

    if (w > 0.0) {
        sign = 1;
    } else if (w < 0.0) {
        sign = -1;
    } else if (x > 0.0) {
        sign = 1;
    } else if (x < 0.0) {
        sign = -1;
    } else if (y > 0.0) {
        sign = 1;
    } else if (y < 0.0) {
        sign = -1;
    } else if (z > 0.0) {
        sign = 1;
    } else if (z < 0.0) {
        sign = -1;
    } else {
        sign = 1;
    }

    canonical->w = (double)sign * w;
    canonical->x = (double)sign * x;
    canonical->y = (double)sign * y;
    canonical->z = (double)sign * z;

    return ADCS_OK;
}

